            graph[v].append((u, color))
            colors.append(('R', i))
        else:
            graph[u].append((v, color))
            graph[v].append((u, color))
            colors.append(('B', i))

    indegree = {v: 0 for v in range(1, n + 1)}
    # first pass: find vertices with outdegree > 1
    odd = [(v, outdeg) for v in range(1, n + 1) if len(graph[v]) > 1]
    to_change = set(odd)
    changed = []
    # process in topological order (highest degree first)
    while odd:
        max_out = None
        for v, outdeg in sorted(odd, key=lambda x: (-x[1], x[0])):
