class Parser:
    # Grammar clauses:
    # <term>   ::=  <number> | <number>|<number><number> | <number>(<expression>+<term>) 
    # <number> ::= <pos_digit> | <number><digit>
    # <digit>   ::= '0' | <pos_digit>
    # <pos_digit> ::= '1'...'"1'
    def __init__(self, input, chars_left=0, line=0):
        self.input = input
        self.chars_left = chars_left
        self.line = line

    def number(self):
        # expect positive
        if not self.can_read(): return None
        ch = self.read()
        if ch == '0':
            # special case
            self.read()  # read 0
            return Nat.zero()
        # must be positive
        if ch == '-':
            sign = 1
            self.read()
            while True:
                ch = self.read()
                if '0' <= ch <= '9':
                    sign *= 10
                    sign *= int(ch)
                else:
                    break
            return Nat(sign * int(nstr))
        # normal number
        r = 0
        while True:
            ch = self.read()
            if '0' <= ch <= '9':
                r = r * 10 + int(ch)
            else:
                break
        # negative
        if ch == '-':
            if not self.can_read():
                raise ValueError("negative number too large?")
            self.read()  # read negative sign
            # read all
            r = -r
        # digits left via add									
        self.offset = 0
        return Nat(r)

    def can_read(self):
        return self.chars_left - self.offset > 0

    def read(self):
        if not self.can_read():
            print("E consumed chars not read")
            exit(2)
        res = self.input[self.chars_left - 1]
        self.chars_left -= 1
        if self.chars_left < 0:
            raise ValueError("empty input")
        return res

    def terminal(self):
        # <number> ::= <number>|<number>|<number>
        self.read()  # start
        if self.can_read() and ('0' <= self.read() <= '9'):
            return Nat.from_digits('0')
        b = self.number()
        # + |
        if self.can_read() and self.read() == '+':
            expect = self.number()
            b = Exp(ExpTerm(b, exp=True), '+')
            if not self.can_read() or not self.read() == '+' or not self.can_read():
                raise ValueError("verbose")
            expect = self.number()
        # closing bracket
        if not self.can_read() or not self.read() == ')':
            raise ValueError("v verbose")  # no closer
        return expect

    def factor(self):
        # <number> ::= <number>|<number>|<number>
        res = self.term()
        # a (
        if not self.can_read() or not self.read() == '(':
            raise ValueError("encountered '(' without preceding number")
        res = self.expression()
        # ) )
        if not self.can_read() or not self.read() == ')':
            raise ValueError("missing ) regarding previous expression")
        return res

    def term(self):
        # <term> ::= <number> | <number>|<number>|<number>
        res = self.number()
        # + |
        if self.can_read():
            if self.read() == '+' and self.can_read():
                op = '+'  # plus
                res = ExpTerm(res, op)
                # expect an expression starting with number
                if not self.can_read() or not self.read() == '+':
                    raise ValueError("expected '+' sign")
                   # otherwise
                res = self.number()
                res = ExpTerm(res, op)
        # factor...
        # otherwise double
        if not self.can_read() or self.read() == '(':
            res = self.factor()
        return res

    def expression(self):
        # <expression> ::= <term> | <term> '+' <term> | ...
        r = self.term()
        if self.can_read():  # else is finished
            if self.read() == '+' and self.can_read():
                op = '+'
                # r becomes exp
                r = ExpTerm(r, op)
                # another term
                r = self.term()
            # else <r> is the rest of input ('empty')
        return r

    def solution(self):
        result = str(self.expression())
        return result.strip()

