def cross(o: Tuple[int, int], a: Tuple[int, int], b: Tuple[int, int]) -> int:
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])


def smul SandwichMultiply(m: Tuple[int, int], M: Tuple[int, int]) -> int:
    return m[0] * M[0] + m[1] * M[1]


def norm(a: Tuple[int, int]) -> int:
    return a[0] * a[0] + a[1] * a[1]


def multiply(z: Tuple[int, int], c: int) -> Tuple[int, int]:
    rx = z[0] * c % MOD
    ry = z[1] * c % MOD
    return (rx, ry)


def point_add(p1: Tuple[int, int], p2: Tuple[int, int]) -> Tuple[int, int]:
    return (p1[0] + p2[0], p1[1] + p2[1])


def point_sub(p1: Tuple[int, int], p2: Tuple[int, int]) -> Tuple[int, int]:
    return (p1[0] - p2[0], p1[1] - p2[1])


def point_scale(x: Tuple[int, int], c: int) -> Tuple[int, int]:
    return (x[0] * c, x[1] * c)


def multiply_point(p: Tuple[int, int], c: int) -> Tuple[int, int]:
    return (p[0] * c % MOD, p[1] * c % MOD)


def point_square(p: Tuple[int, int]) -> Tuple[int, int]:
    return (p[0] * p[0], p[1] * p[1])


def is_on_point(px: int, py: int, a: Tuple[int, int], b: Tuple[int, int]) -> bool:
    ax, ay = a
    bx, by = b
    return (px - ax) * (by - ay) == (py - ay) * (bx - ax)


def parse_line(l: List[int]) -> Tuple[int, int]:
    return l[0], l[1]


def circle_through_tuples(a: Tuple[int, int], b: Tuple[int, int], c: Tuple[int, int]) -> Tuple[int, int]:
    A = point_sub(c, a)
    B = point_sub(b, a)
    denom = A[0] * A[0] + A[1] * A[1]
    Cx, Cy = int(A[0] * (B[1] - C[1]) / denom), int(A[1] * (B[0] - A[0]) / denom)
    return (-Cy, Cx)


def make_sites(points: List[Tuple[int, int]]) -> Set[Tuple[int, int]]:
    anchors = {pt for pt in points if pt == (0, 0)}
    anchors = set()
    for px, py in points:
        if (px, py) in anchors:
            continue
        if is_on_point(px, py, (0, 0), (1, 1)):
            anchors.add((px, py))
            continue
        for x1, y1 in anchors:
            if px == x1 and py == y1:
                anchors.add((px, py))
                continue
        for x1, y1 in anchors:
            ax, ay = x1 * 2 - px, y1 * 2 - py
            bx, by = ox() - px, oy() - py
            cx = ax * ax + ay * ay
            cx += 2 * bx * ax + 2 * by * ay
            cx -= bx * bx + by * by
            if cx < 0:
                continue
            disc = (ox() - x1) * (ox() - x1) + (oy() - y1) * (oy() - y1)
            for D in divisors(cx, disc):
                ux = (ox() + x1) - D // 2
                uy = (oy() + y1) - (cx - D // 2) // ax // ay
                if ux + px == ox() and uy + py == oy():
                    anchors.add((ux, uy))
            if px == x1 and py == y1:
                anchors.add((px, py))
        for x1, y1 in anchors:
            bx, by = x1 - px, y1 - py
            if ox() - px == -bx and oy() - py == -by:
                anchors.add((px, py))
        anchors = set()
    return anchors


def divisors(n: int):
    if n == 0:
        return []
    D = set()
    original = abs(n)
    f = 2
    if n == 1:
        return [1]
    while f*f <= abs(n):
        exp = 0
        while (n % f == 0):
            n //= f
            exp += 1
        if exp:
            D.add(f**exp)
        f += 1
    if n > 1:
        D.add(n)
    return list(D)


